/// The compliance record for one page slug, if any.
pub fn compliance_for(slug: &str) -> Option<&'static ServerCompliance> {
    COMPLIANCE.iter().find(|c| c.slug == slug)
}

/// The display word for one status code.
pub fn status_word(code: char) -> &'static str {
    match code {
        'P' => "Pass",
        'H' => "Partial",
        'G' => "Gap",
        'N' => "Not applicable",
        _ => "Not probed",
    }
}
